// route: /mcp — the Inuberry MCP server (owned here, no longer generated by @lovable.dev/mcp-js).
// A personal developer key (`Authorization: Bearer inbp_…`) is checked here and served by a copy of
// the server bound to that key's user and workspace; every other request goes through OAuth.
import { createFileRoute } from "@tanstack/react-router";

import { createTanStackMcpHandler } from "@lovable.dev/mcp-js/stacks/tanstack";

import mcp, { keyMcp } from "../lib/mcp/index";
import { contextFromPersonalKey, oauthRefusal, PERSONAL_KEY_PREFIX } from "../lib/mcp/personal-key.server";
import { clientIp, overLimit, secretId, tooMany } from "../lib/rate-limit.server";

const options = {
  resourcePath: "/mcp",
  metadataPath: "/.well-known/oauth-protected-resource",
  trustForwardedHost: true,
  trustForwardedProto: true,
};
const oauthHandler = createTanStackMcpHandler(mcp, options);

/** 401 invalid_token: clients drop the token and offer to sign in again. */
function invalidToken(request: Request, description: string) {
  const metadata = new URL(options.metadataPath, request.url).href;
  return new Response(JSON.stringify({ error: "invalid_token", error_description: description }), {
    status: 401,
    headers: {
      "content-type": "application/json",
      "www-authenticate": `Bearer error="invalid_token", error_description="${description}", resource_metadata="${metadata}"`,
    },
  });
}

export const Route = createFileRoute("/mcp")({
  server: {
    handlers: {
      ANY: async (ctx) => {
        const bearer = ctx.request.headers.get("authorization")?.replace(/^Bearer\s+/i, "") ?? "";
        // 120 calls a minute per connection; 60 a minute per address without one.
        if (bearer ? await overLimit(`mcp:${await secretId(bearer)}`, 120, 60) : await overLimit(`mcp-ip:${clientIp(ctx.request)}`, 60, 60)) {
          return tooMany(60, "Too many calls from this connection. Wait a minute and try again.");
        }
        if (!bearer.startsWith(PERSONAL_KEY_PREFIX)) {
          const refusal = bearer ? await oauthRefusal(bearer) : null;
          return refusal ? invalidToken(ctx.request, refusal) : oauthHandler(ctx);
        }
        const keyCtx = await contextFromPersonalKey(bearer);
        if (!keyCtx) return invalidToken(ctx.request, "This Inuberry key is wrong, expired or revoked.");
        return createTanStackMcpHandler(keyMcp(keyCtx), options)(ctx);
      },
    },
  },
});
